<div class="page-title"><div><h2>حساب کاربران</h2><p class="text-muted">پرداخت وجه به کاربر مانده را کاهش می‌دهد و دریافت وجه از کاربر مانده را افزایش می‌دهد.</p></div></div>
<section class="card"><form method="get" class="form-inline mb-3"><input type="hidden" name="route" value="plugin/accounting/accounts"><input class="form-control" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="جستجوی نام، موبایل یا نام کاربری"><select class="form-control" name="balance"><option value="">همه مانده‌ها</option><option value="positive"<?= ($_GET['balance'] ?? '') === 'positive' ? ' selected' : '' ?>>مثبت</option><option value="negative"<?= ($_GET['balance'] ?? '') === 'negative' ? ' selected' : '' ?>>منفی</option><option value="zero"<?= ($_GET['balance'] ?? '') === 'zero' ? ' selected' : '' ?>>صفر</option></select><button class="btn btn-primary" type="submit">جستجو</button></form><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>کاربر</th><th>نقش</th><th>موبایل</th><th>شماره حساب</th><th>مانده</th><th>عملیات</th></tr></thead><tbody><?php foreach (($accounts ?? []) as $account): ?><tr><td><?= e($account['full_name']) ?></td><td><?= e(role_label($account['role'])) ?></td><td dir="ltr"><?= e($account['mobile'] ?: '-') ?></td><td dir="ltr"><?= e($account['account_number'] ?: '-') ?></td><td class="<?= (float) ($account['balance'] ?? 0) >= 0 ? 'proma-accounting-positive' : 'proma-accounting-negative' ?>"><?= money_toman($account['balance']) ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('plugin/accounting/ledger/' . (int) $account['id'])) ?>">مشاهده دفترکل</a></td></tr><?php endforeach; ?><?php if (empty($accounts)): ?><tr><td colspan="6" class="empty">نتیجه‌ای پیدا نشد.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) { return url('plugin/accounting/accounts', ['q' => $_GET['q'] ?? '', 'balance' => $_GET['balance'] ?? '', 'page' => $page]); }) ?></section>
